import"./chunk-WOT6VMZA.js";var n={"The morning after Lantern Night, a little map came floating down with Hazel\u2019s reply.":"S\xE1ng h\xF4m sau \u0110\xEAm \u0110\xE8n L\u1ED3ng, m\u1ED9t t\u1EA5m b\u1EA3n \u0111\u1ED3 nh\u1ECF bay xu\u1ED1ng c\xF9ng l\xE1 th\u01B0 h\u1ED3i \xE2m c\u1EE7a b\xE0 Hazel.","Fernhollow! Hazel\u2019s map says the trail home starts there.":"Fernhollow! B\u1EA3n \u0111\u1ED3 c\u1EE7a b\xE0 n\xF3i con \u0111\u01B0\u1EDDng v\u1EC1 nh\xE0 b\u1EAFt \u0111\u1EA7u t\u1EEB \u0111\xF3.","The friends crossed the lantern bridge together, until a gust of silver mist swept them apart.":"C\xE1c b\u1EA1n c\xF9ng nhau \u0111i qua c\xE2y c\u1EA7u \u0111\xE8n l\u1ED3ng, cho \u0111\u1EBFn khi m\u1ED9t l\xE0n s\u01B0\u01A1ng b\u1EA1c th\u1ED5i t\u1EDBi cu\u1ED1n m\u1ED7i ng\u01B0\u1EDDi m\u1ED9t ng\u1EA3.","Momo? Nori? Everyone? \u2026Okay. One step at a time.":"Momo? Nori? M\u1ECDi ng\u01B0\u1EDDi \u01A1i? \u2026\u0110\u01B0\u1EE3c r\u1ED3i. T\u1EEBng b\u01B0\u1EDBc m\u1ED9t th\xF4i.","Find your friends. Calm the lonely mist. Light the waystones so Hazel can find her way home.":"H\xE3y t\xECm c\xE1c b\u1EA1n. V\u1ED7 v\u1EC1 nh\u1EEFng l\xE0n s\u01B0\u01A1ng c\xF4 \u0111\u01A1n. Th\u1EAFp s\xE1ng c\xE1c \u0111\xE8n \u0111\xE1 d\u1EABn \u0111\u01B0\u1EDDng \u0111\u1EC3 b\xE0 Hazel t\xECm \u0111\u01B0\u1EE3c l\u1ED1i v\u1EC1.","FERNHOLLOW \xB7 Waystones ahead. Please be gentle with the mist. \u2014 H.":"FERNHOLLOW \xB7 Ph\xEDa tr\u01B0\u1EDBc l\xE0 \u0111\xE8n \u0111\xE1 d\u1EABn \u0111\u01B0\u1EDDng. H\xE3y d\u1ECBu d\xE0ng v\u1EDBi s\u01B0\u01A1ng nh\xE9. \u2014 H.","A Mistling! It looks\u2026 sad.":"M\u1ED9t B\xE9 S\u01B0\u01A1ng! Tr\xF4ng n\xF3\u2026 bu\u1ED3n qu\xE1.","Mistlings are lonely wisps of fog. A warm hug is the only way to calm one.":"B\xE9 S\u01B0\u01A1ng l\xE0 nh\u1EEFng l\xE0n s\u01B0\u01A1ng nh\u1ECF c\xF4 \u0111\u01A1n. Ch\u1EC9 c\xF3 m\u1ED9t c\xE1i \xF4m \u1EA5m \xE1p m\u1EDBi l\xE0m ch\xFAng d\u1ECBu l\u1EA1i.","It turned into a firefly! I think it wants to come along.":"N\xF3 bi\u1EBFn th\xE0nh \u0111om \u0111\xF3m r\u1ED3i! H\xECnh nh\u01B0 n\xF3 mu\u1ED1n \u0111i c\xF9ng m\xECnh.","The waystone is cold. Something nearby is still too gloomy for it to light.":"\u0110\xE8n \u0111\xE1 c\xF2n l\u1EA1nh. C\xF3 g\xEC \u0111\xF3 g\u1EA7n \u0111\xE2y v\u1EABn c\xF2n u \xE1m qu\xE1 n\xEAn \u0111\xE8n ch\u01B0a s\xE1ng \u0111\u01B0\u1EE3c.","The waystone glows. Everyone feels warm again, and your journey is saved here.":"\u0110\xE8n \u0111\xE1 b\u1EEBng s\xE1ng. M\u1ECDi ng\u01B0\u1EDDi th\u1EA5y \u1EA5m \xE1p tr\u1EDF l\u1EA1i, v\xE0 h\xE0nh tr\xECnh \u0111\xE3 \u0111\u01B0\u1EE3c l\u01B0u \u1EDF \u0111\xE2y.","The waystone glows. The mist on the bridge melts away like breath on a window.":"\u0110\xE8n \u0111\xE1 b\u1EEBng s\xE1ng. M\xE0n s\u01B0\u01A1ng tr\xEAn c\u1EA7u tan \u0111i nh\u01B0 h\u01A1i th\u1EDF tr\xEAn \xF4 c\u1EEDa k\xEDnh.","Hazel\u2019s lights still work! Hold on, everyone, I\u2019m coming.":"\u0110\xE8n c\u1EE7a b\xE0 v\u1EABn c\xF2n s\xE1ng! M\u1ECDi ng\u01B0\u1EDDi ch\u1EDD nh\xE9, m\xECnh \u0111\u1EBFn \u0111\xE2y.","A thick wall of mist hangs over the bridge. Something warm might clear it.":"M\u1ED9t b\u1EE9c t\u01B0\u1EDDng s\u01B0\u01A1ng d\xE0y ph\u1EE7 k\xEDn c\xE2y c\u1EA7u. C\xF3 l\u1EBD th\u1EE9 g\xEC \u0111\xF3 \u1EA5m \xE1p s\u1EBD l\xE0m n\xF3 tan.","Pip! Oh, Pip! They won\u2019t let me finish my tea!":"Pip! \xD4i, Pip! T\u1EE5i n\xF3 kh\xF4ng cho m\xECnh u\u1ED1ng h\u1EBFt t\xE1ch tr\xE0!","Hold on, Momo. We\u2019ll calm them together!":"C\u1ED1 l\xEAn Momo. M\xECnh c\xF9ng v\u1ED7 v\u1EC1 t\u1EE5i n\xF3 nh\xE9!","Thank you. My paws are still shaking.":"C\u1EA3m \u01A1n b\u1EA1n. Ch\xE2n m\xECnh v\u1EABn c\xF2n run.","Here, moonflower tea for the road. It warms everything it touches.":"\u0110\xE2y, tr\xE0 hoa tr\u0103ng mang theo \u0111\u01B0\u1EDDng. N\xF3 s\u01B0\u1EDFi \u1EA5m m\u1ECDi th\u1EE9 n\xF3 ch\u1EA1m v\xE0o.","Momo joined! Moonflower Tea heals the whole party. Its steam thins the mist on the next bridge.":"Momo \u0111\xE3 nh\u1EADp h\u1ED9i! Tr\xE0 Hoa Tr\u0103ng h\u1ED3i s\u1EE9c cho c\u1EA3 nh\xF3m. H\u01A1i tr\xE0 l\xE0m tan m\xE0n s\u01B0\u01A1ng tr\xEAn c\xE2y c\u1EA7u k\u1EBF ti\u1EBFp.","Stay back! I can handle them. Probably.":"L\xF9i l\u1EA1i! M\xECnh t\u1EF1 lo \u0111\u01B0\u1EE3c. Ch\u1EAFc v\u1EADy.","Nori, you don\u2019t have to do it alone!":"Nori, b\u1EA1n \u0111\xE2u c\u1EA7n ph\u1EA3i m\u1ED9t m\xECnh!","Okay. I couldn\u2019t handle them. Thanks, Pip.":"\u0110\u01B0\u1EE3c r\u1ED3i. M\xECnh kh\xF4ng lo n\u1ED5i th\u1EADt. C\u1EA3m \u01A1n nh\xE9, Pip.","Watch my kite, though. It\u2019s the fastest thing on any island.":"Nh\u01B0ng xem con di\u1EC1u c\u1EE7a m\xECnh n\xE0y. N\xF3 nhanh nh\u1EA5t tr\xEAn m\u1ECDi h\xF2n \u0111\u1EA3o \u0111\u1EA5y.","Nori joined! Kite Dash calms one Mistling twice as much.":"Nori \u0111\xE3 nh\u1EADp h\u1ED9i! Di\u1EC1u L\u01B0\u1EDBt v\u1ED7 v\u1EC1 m\u1ED9t B\xE9 S\u01B0\u01A1ng m\u1EA1nh g\u1EA5p \u0111\xF4i.","Hoo! Visitors on Old Oak Hill. Hazel left the summit path in my care.":"H\xFA! C\xF3 kh\xE1ch l\xEAn \u0110\u1ED3i S\u1ED3i Gi\xE0. B\xE0 Hazel giao con \u0111\u01B0\u1EDDng l\xEAn \u0111\u1EC9nh cho ta tr\xF4ng coi.","It opens only for those who can answer a riddle.":"\u0110\u01B0\u1EDDng ch\u1EC9 m\u1EDF cho ai tr\u1EA3 l\u1EDDi \u0111\u01B0\u1EE3c m\u1ED9t c\xE2u \u0111\u1ED1.","Round and warm, I wake the night. Five of me make the whole sky bright. What am I?":"Tr\xF2n tr\xF2n \u1EA5m \xE1p, ta \u0111\xE1nh th\u1EE9c m\xE0n \u0111\xEAm. N\u0103m chi\u1EBFc nh\u01B0 ta l\xE0m c\u1EA3 b\u1EA7u tr\u1EDDi s\xE1ng l\xEAn. Ta l\xE0 g\xEC?","A lantern":"Chi\u1EBFc \u0111\xE8n l\u1ED3ng","The moon":"M\u1EB7t tr\u0103ng","A firefly":"Con \u0111om \u0111\xF3m","Hoo-hoo, not quite. Think of the clearing on Lantern Night\u2026":"H\xFA h\xFA, ch\u01B0a \u0111\xFAng r\u1ED3i. Ngh\u0129 v\u1EC1 b\xE3i c\u1ECF trong \u0110\xEAm \u0110\xE8n L\u1ED3ng xem\u2026","Splendid! A lantern it is. Every story needs someone to write it down, so I\u2019m coming too.":"Tuy\u1EC7t l\u1EAFm! \u0110\xFAng l\xE0 chi\u1EBFc \u0111\xE8n l\u1ED3ng. C\xE2u chuy\u1EC7n n\xE0o c\u0169ng c\u1EA7n ng\u01B0\u1EDDi ghi l\u1EA1i, n\xEAn ta \u0111i c\xF9ng.","Juniper joined! A Riddle puzzles a Mistling for two turns and shows what it loves.":"Juniper \u0111\xE3 nh\u1EADp h\u1ED9i! C\xE2u \u0110\u1ED1 l\xE0m m\u1ED9t B\xE9 S\u01B0\u01A1ng b\u1ED1i r\u1ED1i hai l\u01B0\u1EE3t v\xE0 cho bi\u1EBFt n\xF3 th\xEDch g\xEC.","The Thunder Sulk sits on the hill path. Calm it, and the last waystone will wake.":"M\xE2y Gi\xF4ng H\u1EDDn D\u1ED7i \u0111ang ng\u1ED3i ch\u1EAFn l\u1ED1i l\xEAn \u0111\u1ED3i. V\u1ED7 v\u1EC1 n\xF3 \u0111i, r\u1ED3i \u0111\xE8n \u0111\xE1 cu\u1ED1i c\xF9ng s\u1EBD th\u1EE9c gi\u1EA5c.","\u2026P-Pip? Is that you?":"\u2026P-Pip? L\xE0 b\u1EA1n \u0111\xF3 h\u1EA3?","I came up last night to keep Hazel\u2019s beacon company. Then the big fog sat on it, and it won\u2019t move.":"T\u1ED1i qua m\xECnh l\xEAn \u0111\xE2y \u0111\u1EC3 \u1EDF c\u1EA1nh ng\u1ECDn \u0111\xE8n hi\u1EC7u c\u1EE7a b\xE0 Hazel. R\u1ED3i \u0111\xE1m s\u01B0\u01A1ng to \u0111\u1EBFn ng\u1ED3i l\xEAn n\xF3, v\xE0 kh\xF4ng ch\u1ECBu \u0111i.","You came all this way alone? Bramble, that\u2019s the bravest thing I\u2019ve ever heard.":"B\u1EA1n \u0111i c\u1EA3 qu\xE3ng \u0111\u01B0\u1EDDng n\xE0y m\u1ED9t m\xECnh sao? Bramble, \u0111\xF3 l\xE0 \u0111i\u1EC1u d\u0169ng c\u1EA3m nh\u1EA5t m\xECnh t\u1EEBng nghe.","I\u2019m still scared. But I can hold a shield. And\u2026 here, a dragon fruit. For courage.":"M\xECnh v\u1EABn s\u1EE3. Nh\u01B0ng m\xECnh c\u1EA7m khi\xEAn \u0111\u01B0\u1EE3c. V\xE0\u2026 \u0111\xE2y, m\u1ED9t qu\u1EA3 thanh long. \u0110\u1EC3 th\xEAm can \u0111\u1EA3m.","Bramble joined! Lantern Shield halves the mist\u2019s chill for two rounds.":"Bramble \u0111\xE3 nh\u1EADp h\u1ED9i! Khi\xEAn \u0110\xE8n L\u1ED3ng gi\u1EA3m m\u1ED9t n\u1EEDa c\xE1i l\u1EA1nh c\u1EE7a s\u01B0\u01A1ng trong hai v\xF2ng.","Hmmmm\u2026 Everyone leaves. The Keeper left. The lights left.":"H\u1EEBmmm\u2026 Ai r\u1ED3i c\u0169ng \u0111i. Ng\u01B0\u1EDDi Gi\u1EEF \u0110\xE8n \u0111\xE3 \u0111i. \xC1nh s\xE1ng c\u0169ng \u0111i.","We came to light the beacon, so Hazel can find her way home.":"T\u1EE5i m\xECnh \u0111\u1EBFn \u0111\u1EC3 th\u1EAFp ng\u1ECDn \u0111\xE8n hi\u1EC7u, \u0111\u1EC3 b\xE0 Hazel t\xECm \u0111\u01B0\u1EE3c \u0111\u01B0\u1EDDng v\u1EC1.","\u2026Then you will leave too. Let the summit stay grey.":"\u2026R\u1ED3i c\xE1c ng\u01B0\u01A1i c\u0169ng s\u1EBD \u0111i. C\u1EE9 \u0111\u1EC3 \u0111\u1EC9nh n\xFAi x\xE1m x\u1ECBt th\u1EBF n\xE0y.","Why\u2026 are you still here?":"Sao\u2026 c\xE1c ng\u01B0\u01A1i v\u1EABn c\xF2n \u1EDF \u0111\xE2y?","Because friends stay. And Hazel left notes, for you too.":"V\xEC b\u1EA1n b\xE8 th\xEC \u1EDF l\u1EA1i. V\xE0 b\xE0 Hazel c\u0169ng \u0111\u1EC3 l\u1EA1i th\u01B0 cho \xF4ng n\u1EEFa.","\u2026Warm. I forgot what warm felt like.":"\u2026\u1EA4m qu\xE1. Ta \u0111\xE3 qu\xEAn m\u1EA5t c\u1EA3m gi\xE1c \u1EA5m \xE1p l\xE0 th\u1EBF n\xE0o.","Old Fog shimmered gold, and a thousand fireflies rose from the summit.":"S\u01B0\u01A1ng Gi\xE0 \xE1nh l\xEAn m\xE0u v\xE0ng, v\xE0 h\xE0ng ngh\xECn con \u0111om \u0111\xF3m bay l\xEAn t\u1EEB \u0111\u1EC9nh n\xFAi.","The beacon blazed. Far across the clouds, a single lantern answered.":"Ng\u1ECDn \u0111\xE8n hi\u1EC7u r\u1EF1c s\xE1ng. Xa t\xEDt b\xEAn kia bi\u1EC3n m\xE2y, m\u1ED9t chi\u1EBFc \u0111\xE8n l\u1ED3ng s\xE1ng l\xEAn \u0111\xE1p l\u1EA1i.","Pip, I saw it: every light, every friend. I\u2019m on my way. Save me a seat on the blanket. \u2014 Grandma Hazel":"Pip, b\xE0 th\u1EA5y r\u1ED3i: t\u1EEBng ng\u1ECDn \u0111\xE8n, t\u1EEBng ng\u01B0\u1EDDi b\u1EA1n. B\xE0 \u0111ang tr\xEAn \u0111\u01B0\u1EDDng v\u1EC1. \u0110\u1EC3 d\xE0nh cho b\xE0 m\u1ED9t ch\u1ED7 tr\xEAn t\u1EA5m kh\u0103n nh\xE9. \u2014 B\xE0 Hazel","The mist hums a sleepy tune, and everyone dozes off\u2026":"S\u01B0\u01A1ng ng\xE2n nga m\u1ED9t kh\xFAc ru, v\xE0 c\u1EA3 nh\xF3m thiu thiu ng\u1EE7\u2026","\u2026and wakes by the last warm waystone, hearts full again.":"\u2026r\u1ED3i t\u1EC9nh d\u1EADy b\xEAn \u0111\xE8n \u0111\xE1 \u1EA5m \xE1p g\u1EA7n nh\u1EA5t, s\u1EE9c l\u1EF1c \u0111\xE3 \u0111\u1EA7y l\u1EA1i.","One of Hazel\u2019s picnic baskets, still packed with fruit.":"M\u1ED9t chi\u1EBFc gi\u1ECF d\xE3 ngo\u1EA1i c\u1EE7a b\xE0 Hazel, v\u1EABn c\xF2n \u0111\u1EA7y tr\xE1i c\xE2y.","Only crumbs and a checked napkin left.":"Ch\u1EC9 c\xF2n v\u1EE5n b\xE1nh v\xE0 m\u1ED9t chi\u1EBFc kh\u0103n \u0103n k\u1EBB \xF4.","Old Fog is curled around the beacon. Maybe a friend nearby knows what happened.":"S\u01B0\u01A1ng Gi\xE0 cu\u1ED9n tr\xF2n quanh ng\u1ECDn \u0111\xE8n hi\u1EC7u. C\xF3 l\u1EBD m\u1ED9t ng\u01B0\u1EDDi b\u1EA1n g\u1EA7n \u0111\xE2y bi\u1EBFt chuy\u1EC7n g\xEC \u0111\xE3 x\u1EA3y ra.","Hazel\u2019s beacon is shining. The whole trail glows behind you.":"\u0110\xE8n hi\u1EC7u c\u1EE7a b\xE0 Hazel \u0111ang t\u1ECFa s\xE1ng. C\u1EA3 con \u0111\u01B0\u1EDDng ph\xEDa sau b\u1EA1n \u0111\u1EC1u l\u1EA5p l\xE1nh.","Pip, if you\u2019re reading this, you found the trail. The mist isn\u2019t wicked, only lonely. Be kind to it. \u2014 H.":"Pip, n\u1EBFu con \u0111ang \u0111\u1ECDc th\u01B0 n\xE0y th\xEC con \u0111\xE3 t\xECm ra con \u0111\u01B0\u1EDDng r\u1ED3i. S\u01B0\u01A1ng kh\xF4ng x\u1EA5u \u0111\xE2u, ch\u1EC9 c\xF4 \u0111\u01A1n th\xF4i. H\xE3y t\u1EED t\u1EBF v\u1EDBi n\xF3 nh\xE9. \u2014 H.","Momo\u2019s moonflowers grow on Fernhollow too. Tea is just warmth you can hold in your paws. \u2014 H.":"Hoa tr\u0103ng c\u1EE7a Momo c\u0169ng m\u1ECDc \u1EDF Fernhollow. Tr\xE0 ch\u1EC9 l\xE0 ch\xFAt h\u01A1i \u1EA5m con c\xF3 th\u1EC3 n\xE2ng trong tay. \u2014 H.","Nori, I never once blamed you for the lantern string. Lights go out. Friends light them again. \u2014 H.":"Nori, b\xE0 ch\u01B0a bao gi\u1EDD tr\xE1ch con chuy\u1EC7n s\u1EE3i d\xE2y \u0111\xE8n. \u0110\xE8n c\xF3 l\xFAc t\u1EAFt. B\u1EA1n b\xE8 s\u1EBD th\u1EAFp l\u1EA1i. \u2014 H.","Juniper keeps my riddles. Here\u2019s one more: what grows bigger the more you share it? \u2014 H.":"Juniper gi\u1EEF c\xE1c c\xE2u \u0111\u1ED1 c\u1EE7a b\xE0. Th\xEAm m\u1ED9t c\xE2u n\u1EEFa nh\xE9: th\u1EE9 g\xEC c\xE0ng chia s\u1EBB c\xE0ng l\u1EDBn th\xEAm? \u2014 H.","Old Fog has kept this beacon company since I left. Please tell it I said thank you. \u2014 H.":"T\u1EEB ng\xE0y b\xE0 \u0111i, S\u01B0\u01A1ng Gi\xE0 v\u1EABn \u1EDF b\xEAn ng\u1ECDn \u0111\xE8n hi\u1EC7u n\xE0y. H\xE3y n\xF3i v\u1EDBi n\xF3 r\u1EB1ng b\xE0 c\u1EA3m \u01A1n nh\xE9. \u2014 H.","Grandma Hazel":"B\xE0 Hazel","Old Fog":"S\u01B0\u01A1ng Gi\xE0",Signpost:"Bi\u1EC3n ch\u1EC9 \u0111\u01B0\u1EDDng","Landing Meadow":"\u0110\u1ED3ng C\u1ECF \u0110\xE1p Ch\xE2n","Lily Pond Glade":"Tr\u1EA3ng H\u1ED3 Sen","Toadstool Wood":"R\u1EEBng N\u1EA5m","Old Oak Hill":"\u0110\u1ED3i S\u1ED3i Gi\xE0","Beacon Summit":"\u0110\u1EC9nh \u0110\xE8n Hi\u1EC7u","Weepy Wisp":"S\u01B0\u01A1ng M\xEDt \u01AF\u1EDBt","Grumbly Puff":"M\xE2y Cau C\xF3","Shy Flicker":"\u0110\u1ED1m S\u01B0\u01A1ng Nh\xFAt Nh\xE1t","Thunder Sulk":"M\xE2y Gi\xF4ng H\u1EDDn D\u1ED7i",Cherries:"Anh \u0111\xE0o","Restores 12 heart to one friend.":"H\u1ED3i 12 tim cho m\u1ED9t b\u1EA1n.",Strawberry:"D\xE2u t\xE2y","Restores 22 heart to one friend.":"H\u1ED3i 22 tim cho m\u1ED9t b\u1EA1n.",Lemon:"Chanh v\xE0ng","Wakes a sleepy friend with half their heart.":"\u0110\xE1nh th\u1EE9c m\u1ED9t b\u1EA1n \u0111ang ng\u1EE7 g\u1EADt v\u1EDBi n\u1EEDa s\u1ED1 tim.",Peach:"\u0110\xE0o","Restores 45 heart to one friend.":"H\u1ED3i 45 tim cho m\u1ED9t b\u1EA1n.",Watermelon:"D\u01B0a h\u1EA5u","Everyone shares: 18 heart each.":"C\u1EA3 nh\xF3m c\xF9ng \u0103n: m\u1ED7i b\u1EA1n h\u1ED3i 18 tim.","Dragon fruit":"Thanh long","Wakes everyone and fills every heart.":"\u0110\xE1nh th\u1EE9c m\u1ECDi ng\u01B0\u1EDDi v\xE0 h\u1ED3i \u0111\u1EA7y tim cho t\u1EA5t c\u1EA3.","Lantern Glow":"\xC1nh \u0110\xE8n L\u1ED3ng","Warm light calms every Mistling a little.":"\xC1nh s\xE1ng \u1EA5m \xE1p v\u1ED7 v\u1EC1 m\u1ECDi B\xE9 S\u01B0\u01A1ng m\u1ED9t ch\xFAt.","Moonflower Tea":"Tr\xE0 Hoa Tr\u0103ng","Heals every friend and wakes sleepy ones.":"H\u1ED3i s\u1EE9c cho c\u1EA3 nh\xF3m v\xE0 \u0111\xE1nh th\u1EE9c c\xE1c b\u1EA1n \u0111ang ng\u1EE7 g\u1EADt.","Kite Dash":"Di\u1EC1u L\u01B0\u1EDBt","A big swoop: twice the calm for one Mistling.":"M\u1ED9t c\xFA l\u01B0\u1EDBt th\u1EADt l\u1EDBn: v\u1ED7 v\u1EC1 m\u1ED9t B\xE9 S\u01B0\u01A1ng g\u1EA5p \u0111\xF4i.",Riddle:"C\xE2u \u0110\u1ED1","Puzzles a Mistling for two turns and shows what it loves.":"L\xE0m m\u1ED9t B\xE9 S\u01B0\u01A1ng b\u1ED1i r\u1ED1i hai l\u01B0\u1EE3t v\xE0 cho bi\u1EBFt n\xF3 th\xEDch g\xEC.","Lantern Shield":"Khi\xEAn \u0110\xE8n L\u1ED3ng","The mist\u2019s chill is halved for two rounds.":"C\xE1i l\u1EA1nh c\u1EE7a s\u01B0\u01A1ng gi\u1EA3m m\u1ED9t n\u1EEDa trong hai v\xF2ng.","Hazel\u2019s notes":"Th\u01B0 c\u1EE7a b\xE0 Hazel","Read Hazel\u2019s notes aloud. Each one you found calms Old Fog.":"\u0110\u1ECDc to nh\u1EEFng l\xE1 th\u01B0 c\u1EE7a b\xE0 Hazel. M\u1ED7i l\xE1 th\u01B0 b\u1EA1n t\xECm \u0111\u01B0\u1EE3c s\u1EBD v\u1ED7 v\u1EC1 S\u01B0\u01A1ng Gi\xE0.","Loves hugs":"Th\xEDch \u0111\u01B0\u1EE3c \xF4m","Loves lantern light":"Th\xEDch \xE1nh \u0111\xE8n l\u1ED3ng","Loves kites":"Th\xEDch di\u1EC1u","Loves riddles":"Th\xEDch c\xE2u \u0111\u1ED1","The trail is lit. Hazel is on her way.":"Con \u0111\u01B0\u1EDDng \u0111\xE3 s\xE1ng. B\xE0 Hazel \u0111ang tr\xEAn \u0111\u01B0\u1EDDng v\u1EC1.","Light the waystone by the bridge.":"Th\u1EAFp \u0111\xE8n \u0111\xE1 c\u1EA1nh c\xE2y c\u1EA7u.","Calm the Mistling in the meadow.":"V\u1ED7 v\u1EC1 B\xE9 S\u01B0\u01A1ng tr\xEAn \u0111\u1ED3ng c\u1ECF.","Cross the bridge and find Momo.":"Qua c\u1EA7u v\xE0 t\xECm Momo.","Follow the steam to Toadstool Wood and find Nori.":"Theo l\xE0n h\u01A1i tr\xE0 \u0111\u1EBFn R\u1EEBng N\u1EA5m v\xE0 t\xECm Nori.","Light the waystone in the wood.":"Th\u1EAFp \u0111\xE8n \u0111\xE1 trong r\u1EEBng.","Climb Old Oak Hill and answer Juniper\u2019s riddle.":"Leo l\xEAn \u0110\u1ED3i S\u1ED3i Gi\xE0 v\xE0 gi\u1EA3i c\xE2u \u0111\u1ED1 c\u1EE7a Juniper.","Light the waystone on Old Oak Hill.":"Th\u1EAFp \u0111\xE8n \u0111\xE1 tr\xEAn \u0110\u1ED3i S\u1ED3i Gi\xE0.","Calm the Thunder Sulk on the hill.":"V\u1ED7 v\u1EC1 M\xE2y Gi\xF4ng H\u1EDDn D\u1ED7i tr\xEAn \u0111\u1ED3i.","Climb to the summit. Someone is hiding there.":"Leo l\xEAn \u0111\u1EC9nh. C\xF3 ai \u0111\xF3 \u0111ang tr\u1ED1n \u1EDF \u0111\xF3.","Calm Old Fog and light Hazel\u2019s beacon.":"V\u1ED7 v\u1EC1 S\u01B0\u01A1ng Gi\xE0 v\xE0 th\u1EAFp \u0111\xE8n hi\u1EC7u c\u1EE7a b\xE0 Hazel.","The trail could not load. Please check your connection and reload.":"Kh\xF4ng t\u1EA3i \u0111\u01B0\u1EE3c con \u0111\u01B0\u1EDDng. H\xE3y ki\u1EC3m tra k\u1EBFt n\u1ED1i r\u1ED3i t\u1EA3i l\u1EA1i trang.","Drag on the left to walk, or tap where to go.":"K\xE9o \u1EDF n\u1EEDa tr\xE1i \u0111\u1EC3 \u0111i, ho\u1EB7c ch\u1EA1m v\xE0o n\u01A1i mu\u1ED1n \u0111\u1EBFn.","Walk with WASD or the arrow keys. E or Space talks.":"\u0110i b\u1EB1ng WASD ho\u1EB7c ph\xEDm m\u0169i t\xEAn. E ho\u1EB7c Space \u0111\u1EC3 n\xF3i chuy\u1EC7n.","Lv {n}":"C\u1EA5p {n}","Start the trail over":"\u0110i l\u1EA1i t\u1EEB \u0111\u1EA7u","Tap again to start over":"Ch\u1EA1m l\u1EA7n n\u1EEFa \u0111\u1EC3 b\u1EAFt \u0111\u1EA7u l\u1EA1i",Read:"\u0110\u1ECDc",Look:"Xem",Open:"M\u1EDF",Rest:"Ngh\u1EC9",Light:"Th\u1EAFp",Talk:"N\xF3i","Hazel\u2019s note {n} of 5":"Th\u01B0 c\u1EE7a b\xE0 Hazel: {n}/5","Everyone rests by the waystone. Hearts are full and the trail is saved.":"C\u1EA3 nh\xF3m ngh\u1EC9 b\xEAn \u0111\xE8n \u0111\xE1. Tim \u0111\xE3 \u0111\u1EA7y v\xE0 h\xE0nh tr\xECnh \u0111\xE3 \u0111\u01B0\u1EE3c l\u01B0u.","Choose Hug, then tap the Mistling.":"Ch\u1ECDn \xD4m, r\u1ED3i ch\u1EA1m v\xE0o B\xE9 S\u01B0\u01A1ng.",sleepy:"ng\u1EE7 g\u1EADt","in {n}":"c\xF2n {n}","{name}\u2019s turn":"L\u01B0\u1EE3t c\u1EE7a {name}",Hug:"\xD4m",Fruit:"Tr\xE1i c\xE2y",Guard:"Ch\u1EE5m l\u1EA1i","A warm hug calms one Mistling.":"M\u1ED9t c\xE1i \xF4m \u1EA5m \xE1p v\u1ED7 v\u1EC1 m\u1ED9t B\xE9 S\u01B0\u01A1ng.","Share fruit from the basket.":"Chia tr\xE1i c\xE2y trong gi\u1ECF.","Brace together: half the chill this round.":"Ch\u1EE5m l\u1EA1i v\u1EDBi nhau: n\u1EEDa c\xE1i l\u1EA1nh trong v\xF2ng n\xE0y.","ready in {n}":"ch\u1EDD {n} l\u01B0\u1EE3t","Tap a Mistling.":"Ch\u1EA1m v\xE0o m\u1ED9t B\xE9 S\u01B0\u01A1ng.","Pick a Mistling: arrows, then Enter. Or click one.":"Ch\u1ECDn B\xE9 S\u01B0\u01A1ng: ph\xEDm m\u0169i t\xEAn r\u1ED3i Enter. Ho\u1EB7c b\u1EA5m v\xE0o n\xF3.","Nobody needs that right now.":"L\xFAc n\xE0y ch\u01B0a ai c\u1EA7n m\xF3n \u0111\xF3.","Who gets the {fruit}? Tap a friend\u2019s card.":"Ai s\u1EBD \u0103n {fruit}? Ch\u1EA1m v\xE0o th\u1EBB c\u1EE7a m\u1ED9t b\u1EA1n.","Tap (or press Space) as the rings meet for a Lovely hug!":"Ch\u1EA1m (ho\u1EB7c nh\u1EA5n Space) khi hai v\xF2ng g\u1EB7p nhau \u0111\u1EC3 c\xF3 c\xE1i \xF4m Tuy\u1EC7t v\u1EDDi!","Lovely!":"Tuy\u1EC7t v\u1EDDi!","It loves that!":"N\xF3 th\xEDch l\u1EAFm!","It\u2019s hiding!":"N\xF3 tr\u1ED1n m\u1EA5t r\u1ED3i!","Puzzled!":"B\u1ED1i r\u1ED1i!","Awake!":"T\u1EC9nh r\u1ED3i!","Lantern Shield!":"Khi\xEAn \u0110\xE8n L\u1ED3ng!",Braced:"\u0110\xE3 ch\u1EE5m l\u1EA1i","Hazel\u2019s notes \xD7{n}":"Th\u01B0 c\u1EE7a b\xE0 \xD7{n}","The mist stirs\u2026":"S\u01B0\u01A1ng \u0111ang c\u1EF1a qu\u1EADy\u2026","Still puzzled\u2026":"V\u1EABn c\xF2n b\u1ED1i r\u1ED1i\u2026","Sulking\u2026":"\u0110ang h\u1EDDn d\u1ED7i\u2026","Hides in the fog!":"Tr\u1ED1n v\xE0o m\xE0n s\u01B0\u01A1ng!","Gathers its fog!":"Gom s\u01B0\u01A1ng l\u1EA1i!","Tap (or press Space) as the mist reaches you to brace!":"Ch\u1EA1m (ho\u1EB7c nh\u1EA5n Space) khi s\u01B0\u01A1ng ch\u1EA1m t\u1EDBi \u0111\u1EC3 ch\u1ED1ng \u0111\u1EE1!","Brave!":"D\u0169ng c\u1EA3m!","Sleepy\u2026":"Bu\u1ED3n ng\u1EE7\u2026","+{n} glow":"+{n} \xE1nh s\xE1ng","Level {n}! Hearts and hugs grow stronger.":"L\xEAn c\u1EA5p {n}! Tim v\xE0 nh\u1EEFng c\xE1i \xF4m \u0111\u1EC1u m\u1EA1nh h\u01A1n.","What teamwork!":"\u0110\u1ED3ng \u0111\u1ED9i tuy\u1EC7t v\u1EDDi!","Friends found":"B\u1EA1n \u0111\xE3 t\xECm th\u1EA5y","Lovely moments":"Kho\u1EA3nh kh\u1EAFc tuy\u1EC7t v\u1EDDi","Minutes on the trail":"S\u1ED1 ph\xFAt tr\xEAn \u0111\u01B0\u1EDDng",Use:"D\xF9ng","The basket is empty. Hazel hid picnic baskets on every islet.":"Gi\u1ECF tr\u1ED1ng r\u1ED3i. B\xE0 Hazel gi\u1EA5u gi\u1ECF d\xE3 ngo\u1EA1i tr\xEAn m\u1ED7i h\xF2n \u0111\u1EA3o nh\u1ECF.","Heart {h}/{max} \xB7 Warmth {w}":"Tim {h}/{max} \xB7 \u1EA4m \xE1p {w}","Level {n} \xB7 {g} glow":"C\u1EA5p {n} \xB7 {g} \xE1nh s\xE1ng","No notes yet. Hazel tucked five of them along the trail.":"Ch\u01B0a c\xF3 th\u01B0 n\xE0o. B\xE0 Hazel \u0111\xE3 gi\u1EA5u n\u0103m l\xE1 th\u01B0 d\u1ECDc \u0111\u01B0\u1EDDng.","Everyone is already full of heart.":"M\u1ECDi ng\u01B0\u1EDDi \u0111\u1EC1u \u0111\xE3 \u0111\u1EA7y tim.","{name} shared the {fruit}.":"{name} \u0111\xE3 \u0103n {fruit}.",Sound:"\xC2m thanh",Menu:"Tr\xECnh \u0111\u01A1n","Skip scene":"B\u1ECF qua c\u1EA3nh",Back:"Quay l\u1EA1i","A LITTLE ADVENTURE FROM THE LANTERN PICNIC":"M\u1ED8T CHUY\u1EBEN PHI\xCAU L\u01AFU NH\u1ECE T\u1EEA BU\u1ED4I D\xC3 NGO\u1EA0I \u0110\xC8N L\u1ED2NG","The Lantern Trail":"Con \u0110\u01B0\u1EDDng \u0110\xE8n L\u1ED3ng","Five friends scattered by the mist. Five islets in the sky. One beacon to light Hazel home.":"N\u0103m ng\u01B0\u1EDDi b\u1EA1n b\u1ECB s\u01B0\u01A1ng th\u1ED5i t\u1EA3n m\xE1t. N\u0103m h\xF2n \u0111\u1EA3o nh\u1ECF tr\xEAn tr\u1EDDi. M\u1ED9t ng\u1ECDn \u0111\xE8n hi\u1EC7u soi \u0111\u01B0\u1EDDng b\xE0 Hazel v\u1EC1 nh\xE0.","Begin the trail":"B\u1EAFt \u0111\u1EA7u h\xE0nh tr\xECnh","Start a new trail":"B\u1EAFt \u0111\u1EA7u h\xE0nh tr\xECnh m\u1EDBi","Continue the trail":"Ti\u1EBFp t\u1EE5c h\xE0nh tr\xECnh","Back to the picnic":"V\u1EC1 bu\u1ED5i d\xE3 ngo\u1EA1i",Language:"Ng\xF4n ng\u1EEF","About 15 minutes \xB7 plays with touch, mouse, keyboard or a gamepad":"Kho\u1EA3ng 15 ph\xFAt \xB7 ch\u01A1i b\u1EB1ng c\u1EA3m \u1EE9ng, chu\u1ED9t, b\xE0n ph\xEDm ho\u1EB7c tay c\u1EA7m","THE LANTERN TRAIL":"CON \u0110\u01AF\u1EDCNG \u0110\xC8N L\u1ED2NG","Hazel is on her way home.":"B\xE0 Hazel \u0111ang tr\xEAn \u0111\u01B0\u1EDDng v\u1EC1 nh\xE0.","Every waystone is lit, and the beacon on the summit shines across the clouds.":"M\u1ECDi \u0111\xE8n \u0111\xE1 \u0111\u1EC1u \u0111\xE3 s\xE1ng, v\xE0 ng\u1ECDn \u0111\xE8n hi\u1EC7u tr\xEAn \u0111\u1EC9nh t\u1ECFa s\xE1ng kh\u1EAFp bi\u1EC3n m\xE2y.","Keep wandering Fernhollow":"D\u1EA1o ti\u1EBFp Fernhollow",FERNHOLLOW:"FERNHOLLOW","Your trail":"H\xE0nh tr\xECnh c\u1EE7a b\u1EA1n",Close:"\u0110\xF3ng",Basket:"Gi\u1ECF",Friends:"B\u1EA1n b\xE8",Notes:"Th\u01B0",Settings:"C\xE0i \u0111\u1EB7t","Timing help":"H\u1ED7 tr\u1EE3 canh nh\u1ECBp","Wider windows for Lovely hugs and Brave braces.":"N\u1EDBi r\u1ED9ng th\u1EDDi \u0111i\u1EC3m cho c\xE1i \xF4m Tuy\u1EC7t v\u1EDDi v\xE0 c\xFA ch\u1ED1ng \u0111\u1EE1 D\u0169ng c\u1EA3m.","Calm motion":"Chuy\u1EC3n \u0111\u1ED9ng \xEAm d\u1ECBu","Less shaking, bobbing and sparkle.":"B\u1EDBt rung l\u1EAFc, nh\u1EA5p nh\xF4 v\xE0 l\u1EA5p l\xE1nh.","Keys: WASD or arrows walk \xB7 E or Space talks and taps \xB7 1\u20134 pick in battle \xB7 Esc menu":"Ph\xEDm: WASD ho\u1EB7c m\u0169i t\xEAn \u0111\u1EC3 \u0111i \xB7 E ho\u1EB7c Space \u0111\u1EC3 n\xF3i v\xE0 ch\u1EA1m \xB7 1\u20134 \u0111\u1EC3 ch\u1ECDn khi v\u1ED7 v\u1EC1 \xB7 Esc m\u1EDF tr\xECnh \u0111\u01A1n","Unrolling Hazel\u2019s map\u2026":"\u0110ang m\u1EDF b\u1EA3n \u0111\u1ED3 c\u1EE7a b\xE0 Hazel\u2026","Try again":"Th\u1EED l\u1EA1i"};export{n as VI};
